<script>
  export default {
    data(){
      return{
        show: false,
        amount: 0,
        unique: 0,
        progArray: []
      }
    },
    methods: {
      handleClose() {
        this.show = false
      },
      doOpen(){
        this.show = true
        this.doQuery();
      },
      doQuery(){
        this.amount = localStorage.getItem('count') || 0;
        let spottedList = localStorage.getItem('spottedList')
        try {
          let spottedListArr = JSON.parse(spottedList);
          this.unique = spottedListArr.length;
          this.progArray = spottedListArr;
        } catch (err) {
          this.unique = 0
        }
        this.$forceUpdate();
      }
    },
    created() {
      this.doQuery();
    }
  }
</script>

<template>
<el-dialog :visible="show" :beforeClose="handleClose" :title="$t('message.statistic')">
  <div>
    <p>{{$t('message.statistic_1_before')}}{{amount}}{{$t('message.statistic_1_after')}}</p>
    <p>{{$t('message.statistic_2_before')}}{{unique}}{{$t('message.statistic_2_after')}}</p>
    <p v-if="unique !== 5">{{$t('message.statistic_3_unfinish')}}</p>
    <p v-else>{{$t('message.statistic_3_finish')}}</p>
    <div class="imageSet">
      <img draggable="false" :class="progArray.indexOf(0) >= 0? '' : 'invisible'" src="@/assets/images/potion_hell.png" alt="">
      <img draggable="false" :class="progArray.indexOf(1) >= 0? '' : 'invisible'" src="@/assets/images/potion_witch.png" alt="">
      <img draggable="false" :class="progArray.indexOf(2) >= 0? '' : 'invisible'" src="@/assets/images/potion_devil.png" alt="">
      <img draggable="false" :class="progArray.indexOf(3) >= 0? '' : 'invisible'" src="@/assets/images/potion_zombie.png" alt="">
      <img draggable="false" :class="progArray.indexOf(4) >= 0? '' : 'invisible'" src="@/assets/images/potion_ghost.png" alt="">
    </div>
  </div>

  <span slot="footer" class="dialog-footer">
    <el-button @click="handleClose">{{$t('message.close')}}</el-button>
  </span>
</el-dialog>
</template>

<style scoped lang="scss">
.imageSet{
  display: flex;
  align-items: center;
  justify-content: space-around;
  margin-top: 16px;
  img{
    width: 12%;
    transform: rotate(-30deg);
    &.invisible{
      filter: brightness(0);
    }
  }
}
</style>
