/**
 * 全局环境配置（请求域名、长连接、公共请求头、会话令牌键名）
 * ------------------------------------------------------------------
 * 业务背景：管理端页面的业务数据目前主要走 utils/auth.js 的前端模拟层；
 *   需要真实后端时由根目录 request.js 统一发请求，本文件就是它的参数来源。
 * 平台差异（uni-app 条件编译，同一常量在各端取值可能不同）：
 *   - H5：开发调试时 HTTP_REQUEST_URL 置空，走 Vite devServer 代理（见根目录
 *     vite.config.js）绕开跨域；发布到独立域名时改回 httpApi，服务器那边配 CORS；
 *   - 微信小程序：域名必须是 https、长连接必须是 wss，且域名要加进小程序后台的
 *     request/socket 合法域名白名单，否则真机上直接失败；
 *   - App：没有域名白名单限制，Form-type 标记为 app，后端据此识别请求来源。
 * 注意事项：
 *   1. TOKENNAME 属于前后端网关的约定，单方面改动会导致登录态读不到；
 *   2. 切换测试/生产环境时 httpApi 与 wsApi 要成对修改，并同步检查小程序白名单；
 *   3. 文件末尾有命名导出和默认导出两份列表，新增配置项时别漏了其中一份。
 */

// H5 专用兜底：只有 H5 能直接读 location，用当前域名拼一个同源 ws 地址；
// 当 wsApi 未配置时，H5 端的长连接回退到这个值。
// #ifdef H5
let VUE_APP_WS_URL_DEFAULT = `ws://${location.hostname}?type=user`
// #endif

// CRMEB 商城模板遗留的占位标记：当前仓库内没有任何调用方（全局搜索无引用），
// 保留只为与模板保持一致；确认外部工程不需要后才可以删。
let openPlantGrass = '-openPlantGrass-'

// 生产接口域名（后端统一网关，request.js 会拼上 /mysql/ 前缀再发请求，
// 域名末尾不要带斜杠，避免拼出 //zx 双斜杠）。
// 行尾注释是历史备选域名，切换环境时参考。
// 网络接口修改此字符 小程序域名要求https
let httpApi = 'http://82.156.171.66:8080';

// 聊天/长连接地址：小程序端必须 wss 否则真机连不上；连接时会拼上 ?type=user，
// type 值沿用商城模板的连接标识（服务端用它识别连接来源），改之前先与后端确认。
// 聊天接口修改此字符 小程序聊天要求wss 例如：wss://mer.crmeb.net
let wsApi = 'wss://82.156.171.66:8080'

// 请求域名 格式： https://您的域名
let HTTP_REQUEST_URL = httpApi
let VUE_APP_WS_URL = `${wsApi}?type=user`
// 上面两行是对外导出的最终值；H5 环境会在下面的条件编译块里再改写一次。

// #ifdef H5
// H5 调试走 Vite devServer 代理（见根目录 vite.config.js），绕开跨域；
// 发布时接口是独立域名的话再改回 httpApi，服务器那边配 CORS
HTTP_REQUEST_URL = ''
// 聊天长连接地址
VUE_APP_WS_URL = wsApi ? `${wsApi}?type=user` : VUE_APP_WS_URL_DEFAULT
// #endif

// 公共请求头：request.js 直接引用这个对象发给 uni.request。
// Form-type 标记请求来源（H5 细分微信内置浏览器/普通浏览器，小程序与 App 各取固定值），
// 条件编译保证每个平台最终只保留一行，不要手动增删。
const HEADER = {
    'Content-Type': 'application/json;charset=UTF-8;',
    //#ifdef H5
    'Form-type': navigator.userAgent.toLowerCase().indexOf("micromessenger") !== -1 ? 'wechat' : 'h5',
    //#endif
    //#ifdef MP
    'Form-type': 'routine',
    //#endif
    //#ifdef APP-PLUS
    'Form-type': 'app',
    //#endif
}

// 回话密钥名称 请勿修改此配置
// 说明：这是请求头里携带登录态的字段名，前后端网关的共同约定；request.js 已预留导入，
// 接入真实 token 后由它读写。单方面改动必须与后端同步，否则登录态读不到。
const TOKENNAME = 'X-Token'

// 缓存时间 0 永久
// 单位：秒；0 表示本地缓存永不过期。当前仓库内没有消费方（模板预留配置，
// CRMEB 惯例是 setStorage 的过期时长），改它之前先确认实际读取方。
const EXPIRE = 0

// 命名导出 + 默认导出两种形态并存（request.js 用的是命名导出）；
// 新增配置项时两处导出列表都要补，避免不同引用方式拿到不一致的值。
export {
    HTTP_REQUEST_URL,
    VUE_APP_WS_URL,
    openPlantGrass,
    HEADER,
    TOKENNAME,
    EXPIRE
}

export default {
    HTTP_REQUEST_URL,
    VUE_APP_WS_URL,
    openPlantGrass,
    HEADER,
    TOKENNAME,
    EXPIRE
}
