<script>
import request from "@/utils/request";
  export default {
    data(){
      return{
        show: false,
        osInfo: {}
      }
    },
    methods: {
      handleClose() {
        this.show = false
      },
      doOpen(){
        this.show = true
      },
      queryVer(){
        try{
          request.get('fetchVer.jsp', '', { noVerify: true, noAuth: true }).then(res => {
            console.log(res)
            this.osInfo = res.data;
          }).catch(err => {
            this.$message.error(this.$t('message.server_error'));
          })
        }
       catch (err){
          this.$message.error(this.$t('message.server_error'));
        }
      }
    },
    created() {
      this.queryVer();
    }
  }
</script>

<template>
<el-dialog :visible="show" :beforeClose="handleClose" :title="$t('message.about')">
  <div>
    <p>{{$t('message.about_1')}}</p>
    <p>2026 Kirbysfan</p>
    <p>Powered by {{osInfo.linuxDistroName}} {{osInfo.linuxDistroVersion}} & Vue 2.6.14</p>
    <p>{{$t('message.about_4')}}</p>
    <p>{{$t('message.about_5')}}Witch Treat Magic (ウィッチトリート★マジック) by <a style="color: #CE93D8" href="https://picomusic.booth.pm">Pico Music</a></p>
    <p>{{$t('message.about_6')}}</p>
  </div>

  <span slot="footer" class="dialog-footer">
    <el-button @click="handleClose">{{$t('message.close')}}</el-button>
  </span>
</el-dialog>
</template>

