<script>
import aboutPopup from '@/components/aboutPopup.vue';
import progressPopup from "@/components/progressPopup.vue";
import request from "@/utils/request";
export default {
  components: {
    aboutPopup,
    progressPopup
  },
  data(){
    return{
      clickable: true,
      showProg: false
    }
  },
  methods: {
    doStart(){
      if (!this.clickable){
        return false;
      }
      this.clickable = false;
      document.getElementById('potion0').style.opacity = 0;
      setTimeout(() => {this.$router.replace('/story')}, 1000)

    },
    testQuery(){
      let sql = 'select * from halloween2026_keys;';
      request.post('getDataListBySql.jsp', { "sqlstring": [sql] },
          { noVerify: true, noAuth: true }).then(res => {}).catch(err => {
        this.$message.error(`There's something wrong with the data...!`);
      })
    },
    openAbout(){
      this.$refs.popup.doOpen();
    },
    openProg(){
      this.$refs.prog.doOpen();
    },
    openQuit(){
      var r=confirm(this.$t('message.exit_prompt'));
      if (r){
        window.history.back();
      }
    },
    doOpenSound(){
      this.$emit('openSettings', false)
    }
  },
  created() {
    // this.testQuery();
    let spottedList = localStorage.getItem('spottedList')
    if (spottedList) {
      try {
        let spottedListArr = JSON.parse(spottedList)
        this.showProg = spottedListArr.length > 0
      } catch (err) {
        this.showProg = false;
      }
    }

  }
}
</script>

<template>
  <div class="clickpotion">
    <div class="potion_outer">
      <div class="potion_inner" id="potion0">
        <button class="startbtn" @click="doStart">{{this.$t('message.menu_play')}}</button>
        <span @click="openProg" v-if="showProg">{{this.$t('message.statistic')}}</span>
        <span @click="doOpenSound">{{this.$t('message.settings')}}</span>
        <span @click="openAbout">{{this.$t('message.menu_about')}}</span>
        <span @click="openQuit">{{this.$t('message.menu_quit')}}</span>
      </div>
    </div>
    <about-popup ref="popup"></about-popup>
    <progress-popup ref="prog"></progress-popup>
  </div>
</template>

<style scoped lang="scss">
@media (orientation: portrait){
  .potion_outer {
    width: 100% !important;
    height: auto !important;
  }
  .potion_inner{
    button{
      font-size: 6vw !important;
    }
    span{
      font-size: 4vw !important;
      margin-top: 12px;
    }
  }
  .hint_text{
    font-size: 4vw;
  }
}
.clickpotion {
  width: 100%;
  height: 100vh;
  background-color: #ab47bc;
  overflow: hidden;
  user-select: none;
  display: flex;
  align-items: center;
  justify-content: center;

  .potion_outer {
    aspect-ratio: 1259/1575;
    width: auto;
    height: 100%;
    margin: 0 auto;
    background-color: black;
    position: relative;
    .potion_inner {
      width: auto;
      height: 100%;
      position: relative;
      background-color: black;
      transition: opacity 1000ms;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      *{
        font-family: "Cherry Bomb One", sans-serif;
      }
      button{
        width: 60%;
        height: 10%;
        min-height: 48px;
        border-radius: 100vh;
        background-color: #a1529b;
        border: none;
        font-size: 3.8vh;
        color: white;
        box-shadow: 0 0 8px white;
        cursor: pointer;
        transition: 300ms;
        &:hover{
          box-shadow: 0 0 24px white;
        }
      }
      span{
        color: white;
        font-size: 2.8vh;
        margin-top: 12px;
        cursor: pointer;
      }
    }
  }
}
</style>
